<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { ElMessage, ElMessageBox, type UploadFile, type UploadFiles, type UploadRequestOptions } from 'element-plus'
import * as echarts from 'echarts'
import { api } from '../api'
import { useAuth } from '../stores/auth'

const props = defineProps<{ active: string }>()
const auth = useAuth()
const busy = ref(false), rows = ref<any[]>([]), stats = ref<any>(null), labs = ref<any[]>([]), cats = ref<any[]>([]), equipment = ref<any[]>([]), userOptions = ref<any[]>([])
const keyword = ref(''), dialog = ref(false), detailDialog = ref(false), detail = ref<any>({}), editId = ref<number | null>(null), chartEl = ref<HTMLElement>(), page = ref(1), total = ref(0), form = ref<any>({})
const repairUploading = ref(false), repairFiles = ref<UploadFile[]>([])
const faultTypes = ['无法开机', '运行异常', '测量不准', '部件损坏', '网络或软件故障', '安全隐患', '其他']
const admin = computed(() => ['LAB_ADMIN', 'SYS_ADMIN'].includes(auth.user?.role)), sysadmin = computed(() => auth.user?.role === 'SYS_ADMIN')
const title = computed(() => props.active === '设备档案' ? '设备档案' : props.active === '预约管理' ? (admin.value ? '预约审批' : '我的预约') : props.active === '报修工单' ? '报修与维修' : props.active)
const columns = computed(() => props.active === '设备档案' ? [['code', '设备编号'], ['name', '设备名称'], ['category', '分类'], ['laboratory', '所属实验室'], ['ownerName', '责任人'], ['status', '状态']] : props.active === '预约管理' ? [['equipment_name', '设备'], ['starts_at', '开始时间'], ['ends_at', '结束时间'], ['purpose', '使用目的'], ['status', '状态']] : props.active === '报修工单' ? [['equipment_name', '设备'], ['reporter_name', '报修人'], ['fault_type', '故障类型'], ['status', '工单状态'], ['created_at', '提交时间']] : props.active === '用户管理' ? [['username', '账号'], ['realName', '姓名'], ['role', '角色'], ['email', '邮箱'], ['enabled', '启用']] : props.active === '实验室与分类' ? [['dataType', '类型'], ['name', '名称'], ['location', '位置'], ['description', '说明']] : [['title', '标题'], ['content', '内容'], ['read_at', '阅读时间'], ['created_at', '时间']])

async function load() { busy.value = true; try { if (props.active === '概览') { if (admin.value) { stats.value = await api.get('/stats'); await drawChart() } else rows.value = await api.get('/reservations') } else if (props.active === '设备档案') { const result: any = await api.get('/equipment', { params: { page: page.value, size: 10, keyword: keyword.value } }); rows.value = result.items; total.value = result.total } else if (props.active === '预约管理') rows.value = admin.value ? await api.get('/reservations/pending') : await api.get('/reservations'); else if (props.active === '报修工单') rows.value = await api.get('/repairs'); else if (props.active === '用户管理') rows.value = await api.get('/admin/users'); else if (props.active === '实验室与分类') { const [labData, categoryData]: any[] = await Promise.all([api.get('/labs'), api.get('/categories')]); labs.value = labData; cats.value = categoryData; rows.value = [...labData.map((x: any) => ({ ...x, dataType: '实验室', kind: '实验室' })), ...categoryData.map((x: any) => ({ ...x, dataType: '设备分类', kind: '分类' }))] } else if (props.active === '站内通知') rows.value = await api.get('/notifications') } finally { busy.value = false } }
async function drawChart() { await nextTick(); if (!chartEl.value || !stats.value?.byLab) return; const chart = echarts.getInstanceByDom(chartEl.value) || echarts.init(chartEl.value); chart.setOption({ tooltip: { trigger: 'axis' }, grid: { left: 40, right: 20, top: 25, bottom: 30 }, xAxis: { type: 'category', data: stats.value.byLab.map((x: any) => x.laboratory) }, yAxis: { type: 'value' }, series: [{ type: 'bar', data: stats.value.byLab.map((x: any) => x.bookings), barMaxWidth: 36, itemStyle: { color: '#3c8c7a' } }] }) }
async function open(row?: any) { editId.value = row?.id ?? null; form.value = row ? { ...row } : { status: 'AVAILABLE', participants: 1 }; repairFiles.value = []; if (props.active === '设备档案') { const [labData, categoryData, users]: any[] = await Promise.all([api.get('/labs'), api.get('/categories'), api.get('/users/options')]); labs.value = labData; cats.value = categoryData; userOptions.value = users } if (props.active === '预约管理' || props.active === '报修工单') equipment.value = (await api.get<any>('/equipment', { params: { page: 1, size: 100, status: 'AVAILABLE' } })).items; dialog.value = true }
function toUtc(value: string) { return new Date(value).toISOString().slice(0, 19) }
async function save() { if (props.active === '设备档案') editId.value ? await api.put(`/equipment/${editId.value}`, form.value) : await api.post('/equipment', form.value); else if (props.active === '预约管理') { if (!form.value.equipmentId || !form.value.startsAt || !form.value.endsAt || !form.value.purpose?.trim()) return ElMessage.warning('请完整填写设备、预约时间和使用目的'); await api.post('/reservations', { ...form.value, startsAt: toUtc(form.value.startsAt), endsAt: toUtc(form.value.endsAt) }) } else if (props.active === '报修工单') { if (!form.value.equipmentId) return ElMessage.warning('请选择报修设备'); if (!form.value.faultType) return ElMessage.warning('请选择故障类型'); if (!form.value.description?.trim()) return ElMessage.warning('请填写故障描述'); if (repairUploading.value) return ElMessage.warning('图片正在上传，请稍候'); await api.post(`/repairs/equipment/${form.value.equipmentId}`, form.value) } else if (props.active === '用户管理') editId.value ? await api.put(`/admin/users/${editId.value}`, form.value) : await api.post('/admin/users', form.value); else if (props.active === '实验室与分类') { const root = form.value.kind === '分类' ? '/admin/categories' : '/admin/labs'; editId.value ? await api.put(`${root}/${editId.value}`, form.value) : await api.post(root, form.value) } dialog.value = false; ElMessage.success('已保存'); await load() }
async function uploadRepairImage(options: UploadRequestOptions) { repairUploading.value = true; try { const result: any = await api.upload('/uploads/repair-image', options.file); form.value.imageUrls = result.url; options.onSuccess(result); ElMessage.success('图片上传成功') } catch (error) { options.onError(error as any) } finally { repairUploading.value = false } }
function removeRepairImage(_file: UploadFile, files: UploadFiles) { repairFiles.value = files; if (!files.length) form.value.imageUrls = '' }
async function showDetail(row: any) { detail.value = props.active === '设备档案' ? await api.get(`/equipment/${row.id}`) : await api.get(`/repairs/${row.id}`); detailDialog.value = true }
async function review(row: any, decision: string) { const { value } = await ElMessageBox.prompt('填写审核意见', '预约审核'); await api.post(`/reservations/${row.id}/review`, { decision, comment: value }); await load() }
async function cancel(row: any) { await ElMessageBox.confirm('确定取消该预约？', '确认操作'); await api.post(`/reservations/${row.id}/cancel`); await load() }
async function process(row: any) { const { value } = await ElMessageBox.prompt('填写维修说明；完成时输入“恢复”将设备恢复为可预约', '维修处理'); const status = row.status === 'OPEN' ? 'PROCESSING' : row.status === 'PROCESSING' ? 'WAIT_ACCEPTANCE' : 'COMPLETED'; await api.post(`/repairs/${row.id}/process`, { status, note: value, restoreAvailable: status === 'COMPLETED' && value.includes('恢复') }); await load() }
async function markRead(row: any) { await api.post(`/notifications/${row.id}/read`); await load() }
function statusType(status: string) { return ({ AVAILABLE: 'success', MAINTENANCE: 'warning', DISABLED: 'info', PENDING: 'warning', APPROVED: 'success', REJECTED: 'danger', CANCELLED: 'info', OPEN: 'warning', PROCESSING: 'primary', WAIT_ACCEPTANCE: 'warning', COMPLETED: 'success' } as any)[status] || 'info' }
watch(() => props.active, load)
onMounted(async () => { const me: any = await api.get('/auth/me'); auth.user = Array.isArray(me) ? me[0] : me; await load() })
</script>

<template><div>
  <template v-if="active === '概览'"><div class="page-heading"><div><div class="eyebrow">OVERVIEW</div><h1>运营概览</h1><p>实验室设备与服务运行状态</p></div><el-button v-if="admin" @click="load">刷新数据</el-button></div><template v-if="admin && stats"><div class="metric-grid"><div class="metric"><span>设备总数</span><b>{{ stats.equipment.total || 0 }}</b><small>当前在册设备</small></div><div class="metric"><span>可预约</span><b class="green">{{ stats.equipment.available || 0 }}</b><small>开放预约设备</small></div><div class="metric"><span>维修中</span><b class="amber">{{ stats.equipment.maintenance || 0 }}</b><small>待恢复设备</small></div><div class="metric"><span>预约通过率</span><b>{{ stats.reservations.reviewed ? Math.round(stats.reservations.approved / stats.reservations.reviewed * 100) : 0 }}%</b><small>已审核预约</small></div></div><div class="data-section"><div class="section-title"><div><h3>各实验室预约量</h3><span>累计预约记录；使用时长按已通过和已完成预约计算</span></div></div><div ref="chartEl" class="chart"></div></div></template><el-empty v-else description="请选择左侧功能查看您的预约和设备"/></template>
  <template v-else><div class="page-heading"><div><div class="eyebrow">MANAGEMENT</div><h1>{{ title }}</h1><p>{{ active === '设备档案' ? '实验室设备清单与状态' : active === '预约管理' ? '提交预约并跟踪审批状态' : active === '报修工单' ? '故障申报与维修处理记录' : '' }}</p></div><div class="heading-actions"><el-input v-if="active === '设备档案'" v-model="keyword" placeholder="搜索设备名称或编号" clearable @keyup.enter="load" @clear="load"/><el-button v-if="active === '设备档案' && admin" type="primary" @click="open()">新增设备</el-button><el-button v-if="active === '预约管理' && !admin" type="primary" @click="open()">提交预约</el-button><el-button v-if="active === '报修工单' && !admin" type="primary" @click="open()">提交报修</el-button><el-button v-if="active === '用户管理' && sysadmin" type="primary" @click="open()">新增用户</el-button><el-dropdown v-if="active === '实验室与分类' && sysadmin"><el-button type="primary">新增基础数据</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="form = { kind: '实验室' }; editId = null; dialog = true">新增实验室</el-dropdown-item><el-dropdown-item @click="form = { kind: '分类' }; editId = null; dialog = true">新增设备分类</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></div><div class="data-section"><el-table v-loading="busy" :data="rows" stripe empty-text="暂无数据"><el-table-column v-for="column in columns" :key="column[0]" :prop="column[0]" :label="column[1]" min-width="125"><template #default="scope"><el-tag v-if="column[0] === 'status'" :type="statusType(scope.row[column[0]])">{{ scope.row[column[0]] }}</el-tag><span v-else-if="column[0] === 'enabled'">{{ scope.row[column[0]] ? '是' : '否' }}</span><span v-else>{{ scope.row[column[0]] ?? '—' }}</span></template></el-table-column><el-table-column label="操作" fixed="right" width="220"><template #default="scope"><template v-if="active === '预约管理'"><el-button v-if="admin && scope.row.status === 'PENDING'" link type="success" @click="review(scope.row, 'APPROVED')">通过</el-button><el-button v-if="admin && scope.row.status === 'PENDING'" link type="danger" @click="review(scope.row, 'REJECTED')">驳回</el-button><el-button v-if="!admin && ['PENDING', 'APPROVED'].includes(scope.row.status)" link type="danger" @click="cancel(scope.row)">取消</el-button></template><el-button v-if="['设备档案', '报修工单'].includes(active)" link @click="showDetail(scope.row)">详情</el-button><el-button v-if="active === '报修工单' && admin && !['COMPLETED', 'REJECTED'].includes(scope.row.status)" link type="primary" @click="process(scope.row)">处理</el-button><el-button v-if="active === '站内通知' && !scope.row.read_at" link type="primary" @click="markRead(scope.row)">标为已读</el-button><el-button v-if="(active === '设备档案' && admin) || (active === '用户管理' && sysadmin) || (active === '实验室与分类' && sysadmin)" link type="primary" @click="open(scope.row)">编辑</el-button></template></el-table-column></el-table><el-pagination v-if="active === '设备档案'" v-model:current-page="page" :page-size="10" :total="total" layout="total,prev,pager,next" @current-change="load"/></div></template>

  <el-dialog v-model="dialog" :title="editId ? '编辑' : '新增'" width="580px"><el-form label-position="top"><template v-if="active === '设备档案'"><div class="form-grid"><el-form-item label="设备编号"><el-input v-model="form.code"/></el-form-item><el-form-item label="设备名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="设备分类"><el-select v-model="form.categoryId"><el-option v-for="x in cats" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="所属实验室"><el-select v-model="form.labId"><el-option v-for="x in labs" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="品牌型号"><el-input v-model="form.brandModel"/></el-form-item><el-form-item label="存放位置"><el-input v-model="form.location"/></el-form-item><el-form-item label="责任人"><el-select v-model="form.ownerId" clearable><el-option v-for="x in userOptions" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="购置日期"><el-date-picker v-model="form.purchaseDate" type="date" value-format="YYYY-MM-DD"/></el-form-item></div><el-form-item label="设备说明"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="使用规则"><el-input v-model="form.usageRules" type="textarea"/></el-form-item><el-form-item label="图片地址"><el-input v-model="form.imageUrl"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="可预约" value="AVAILABLE"/><el-option label="维修中" value="MAINTENANCE"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item></template><template v-else-if="active === '预约管理'"><el-form-item label="设备" required><el-select v-model="form.equipmentId" placeholder="请选择设备"><el-option v-for="x in equipment" :key="x.id" :value="x.id" :label="x.name"/></el-select></el-form-item><el-form-item label="开始时间" required><el-date-picker v-model="form.startsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="结束时间" required><el-date-picker v-model="form.endsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="使用目的" required><el-input v-model="form.purpose"/></el-form-item><el-form-item label="参与人数"><el-input-number v-model="form.participants" :min="1"/></el-form-item></template><template v-else-if="active === '报修工单'"><el-form-item label="设备" required><el-select v-model="form.equipmentId" placeholder="请选择设备"><el-option v-for="x in equipment" :key="x.id" :value="x.id" :label="x.name"/></el-select></el-form-item><el-form-item label="故障类型" required><el-select v-model="form.faultType" placeholder="请选择故障类型"><el-option v-for="type in faultTypes" :key="type" :label="type" :value="type"/></el-select></el-form-item><el-form-item label="故障描述" required><el-input v-model="form.description" type="textarea" :rows="4" maxlength="1000" show-word-limit/></el-form-item><el-form-item label="故障图片"><el-upload v-model:file-list="repairFiles" list-type="picture-card" accept="image/jpeg,image/png,image/webp,image/gif" :limit="1" :http-request="uploadRepairImage" :on-remove="removeRepairImage"><span>上传图片</span><template #tip><div class="upload-tip">支持 JPG、PNG、WEBP、GIF，最大 5MB</div></template></el-upload></el-form-item></template><template v-else-if="active === '用户管理'"><el-form-item label="用户名"><el-input v-model="form.username" :disabled="!!editId"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.realName"/></el-form-item><el-form-item v-if="!editId" label="初始密码"><el-input v-model="form.password" type="password"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role"><el-option label="普通用户" value="USER"/><el-option label="实验室管理员" value="LAB_ADMIN"/><el-option label="系统管理员" value="SYS_ADMIN"/></el-select></el-form-item><el-form-item v-if="editId" label="启用"><el-switch v-model="form.enabled"/></el-form-item></template><template v-else><el-form-item label="类型"><el-select v-model="form.kind" :disabled="!!editId"><el-option label="实验室" value="实验室"/><el-option label="设备分类" value="分类"/></el-select></el-form-item><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item v-if="form.kind === '实验室'" label="位置"><el-input v-model="form.location"/></el-form-item><el-form-item v-else label="说明"><el-input v-model="form.description"/></el-form-item></template></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="repairUploading" @click="save">保存</el-button></template></el-dialog>

  <el-dialog v-model="detailDialog" :title="active === '设备档案' ? '设备详情' : '维修工单详情'" width="680px"><template v-if="active === '设备档案'"><img v-if="detail.image_url" class="detail-image" :src="detail.image_url" alt="设备图片"><el-descriptions :column="2" border><el-descriptions-item label="编号">{{ detail.code }}</el-descriptions-item><el-descriptions-item label="名称">{{ detail.name }}</el-descriptions-item><el-descriptions-item label="分类">{{ detail.category }}</el-descriptions-item><el-descriptions-item label="实验室">{{ detail.laboratory }}</el-descriptions-item><el-descriptions-item label="品牌型号">{{ detail.brand_model || '—' }}</el-descriptions-item><el-descriptions-item label="责任人">{{ detail.ownerName || '—' }}</el-descriptions-item><el-descriptions-item label="存放位置">{{ detail.location || '—' }}</el-descriptions-item><el-descriptions-item label="购置日期">{{ detail.purchase_date || '—' }}</el-descriptions-item><el-descriptions-item label="使用规则" :span="2">{{ detail.usage_rules || '—' }}</el-descriptions-item><el-descriptions-item label="说明" :span="2">{{ detail.description || '—' }}</el-descriptions-item></el-descriptions></template><template v-else><img v-if="detail.ticket?.image_urls" class="detail-image" :src="detail.ticket.image_urls" alt="故障图片"><el-descriptions :column="2" border><el-descriptions-item label="设备">{{ detail.ticket?.equipment_name }}</el-descriptions-item><el-descriptions-item label="状态">{{ detail.ticket?.status }}</el-descriptions-item><el-descriptions-item label="故障类型">{{ detail.ticket?.fault_type }}</el-descriptions-item><el-descriptions-item label="费用">{{ detail.ticket?.cost ?? '—' }}</el-descriptions-item><el-descriptions-item label="故障描述" :span="2">{{ detail.ticket?.description }}</el-descriptions-item><el-descriptions-item label="维修结果" :span="2">{{ detail.ticket?.result || '—' }}</el-descriptions-item></el-descriptions><el-timeline class="repair-timeline"><el-timeline-item v-for="record in detail.records" :key="record.id" :timestamp="record.created_at">{{ record.status }} · {{ record.note || '无备注' }}</el-timeline-item></el-timeline></template></el-dialog>
</div></template>
